def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objs.append((min(x for y, x in cells), color, cells))

    objs.sort()
    out = [[0] * w for _ in range(h)]
    occupied = set()

    for _, color, cells in objs:
        cells = list(cells)

        # First object goes to the northwest corner.
        if not occupied:
            dr = min(y for y, x in cells)
            dc = min(x for y, x in cells)
            cells = [(y-dr, x-dc) for y, x in cells]
        else:
            # Slide north, then west, until the next step would leave the
            # grid or pass through the already placed arrangement.
            for dy, dx in ((-1, 0), (0, -1)):
                while True:
                    nxt = [(y+dy, x+dx) for y, x in cells]
                    if any(y < 0 or x < 0 or y >= h or x >= w for y, x in nxt):
                        break
                    if any((y, x) in occupied for y, x in nxt):
                        # Permit the final contact/overlap.
                        cells = nxt
                        break
                    cells = nxt

        for y, x in cells:
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
                occupied.add((y, x))

    return out
